parameters.jsCode:
const chatInput =
  String(
    $json.chatInput || ''
  ).trim();

const match =
  chatInput
    .toUpperCase()
    .match(
      /AUTH-\d{3}(?:-V\d+)?/
    );

if (!match) {
  return [
    {
      json: {
        chat_input:
          chatInput,

        case_id_found:
          false,

        case_run_id:
          '',

        submission_version:
          null,

        processing_mode:
          'MOCK',

        persist_results:
          true,

        session_id:
          $json.sessionId || ''
      }
    }
  ];
}

const caseRunId =
  match[0];

const versionMatch =
  caseRunId.match(
    /-V(\d+)$/
  );

return [
  {
    json: {
      chat_input:
        chatInput,

      case_id_found:
        true,

      case_run_id:
        caseRunId,

      submission_version:
        versionMatch
          ? Number(versionMatch[1])
          : 1,

      processing_mode:
        'MOCK',

      persist_results:
        true,

      session_id:
        $json.sessionId || ''
    }
  }
];

const caseRow =
  $json || {};

const found =
  Boolean(
    String(
      caseRow.Case_Run_ID || ''
    ).trim()
  );

return [
  {
    json: {
      case_found:
        found,

      requested_case_run_id:
        $('Resolve Case Request')
          .first()
          .json
          .case_run_id,

      case_row:
        found
          ? caseRow
          : null
    }
  }
];

const request =
  $('Resolve Case Request')
    .first()
    .json;

const caseCheck =
  $('Check Case Exists')
    .first()
    .json;

const caseRow =
  caseCheck.case_row;

if (!caseRow) {
  throw new Error(
    'Prepare Agent Context could not find the resolved synthetic case.'
  );
}

/*
The current input contains the rows returned by
Get Existing Runtime Results for THIS execution of the node.
When Always Output Data returns an empty placeholder, the filter
below removes it.
*/
const existingResults =
  $input
    .all()
    .map(item => item.json)
    .filter(row =>
      String(
        row.check_type || ''
      ).trim()
    )
    .sort(
      (a, b) =>
        Number(a.sequence || 0) -
        Number(b.sequence || 0)
    );

function splitSemi(value) {
  return String(value || '')
    .split(';')
    .map(item => item.trim())
    .filter(Boolean);
}

function safeParse(value) {
  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return {
      parse_error: true,
      raw_value: String(value),
    };
  }
}

function toBoolean(value) {
  return (
    value === true ||
    String(value).toLowerCase() === 'true' ||
    String(value).toUpperCase() === 'YES'
  );
}

const mandatorySequence = [
  {
    sequence: 1,
    check_type: 'DOCUMENT_EXTRACTION',
    tool_name: 'Document Checks',
  },
  {
    sequence: 2,
    check_type: 'BUSINESS_VALIDATION',
    tool_name: 'Business Validation',
  },
  {
    sequence: 3,
    check_type: 'IDENTITY_VALIDATION',
    tool_name: 'Identity Validation',
  },
  {
    sequence: 4,
    check_type: 'AUTHORITY_VALIDATION',
    tool_name: 'Authority Validation',
  },
  {
    sequence: 5,
    check_type: 'SYSTEM_DATA_CHECK',
    tool_name: 'System Data Check',
  },
  {
    sequence: 6,
    check_type: 'FINANCIAL_CHECK',
    tool_name: 'Financial Check',
  },
  {
    sequence: 7,
    check_type: 'FINAL_VERIFICATION',
    tool_name: 'Final Verification',
  },
];

const normalisedResults =
  existingResults.map(row => {
    const status =
      String(row.status || '')
        .trim()
        .toUpperCase();

    const ruleIds =
      splitSemi(row.rule_ids);

    const findings =
      safeParse(
        row.findings_json
      );

    return {
      result_id:
        row.result_id,

      sequence:
        Number(row.sequence || 0),

      agent_id:
        row.agent_id,

      utility_name:
        row.utility_name,

      check_type:
        String(
          row.check_type || ''
        )
          .trim()
          .toUpperCase(),

      status,

      findings,

      rule_ids:
        ruleIds,

      reason_codes:
        splitSemi(
          row.reason_codes
        ),

      evidence_references:
        splitSemi(
          row.evidence_references
        ),

      confidence:
        Number(
          row.confidence || 0
        ),

      human_review_required:
        toBoolean(
          row.human_review_required
        ),

      recommended_next_step:
        row.recommended_next_step || '',

      resolved_by_additional_evidence:
        ruleIds.includes(
          'EVID-001'
        ) ||
        findings.evidence_resolution === true,

      superseded:
        toBoolean(
          row.superseded
        ),
    };
  });

const passingStatuses =
  new Set([
    'PASS',
    'PASS_WITH_FLAG',
  ]);

const passingCheckTypes =
  new Set(
    normalisedResults
      .filter(result =>
        passingStatuses.has(
          result.status
        )
      )
      .map(result =>
        result.check_type
      )
  );

const completedMandatoryChecks =
  mandatorySequence
    .filter(check =>
      passingCheckTypes.has(
        check.check_type
      )
    )
    .map(check =>
      check.check_type
    );

const pendingMandatoryChecks =
  mandatorySequence
    .filter(check =>
      !passingCheckTypes.has(
        check.check_type
      )
    )
    .map(check =>
      check.check_type
    );

const nextRequiredCheck =
  pendingMandatoryChecks[0] || '';

const evidenceResolvedChecks =
  normalisedResults
    .filter(result =>
      result.resolved_by_additional_evidence
    )
    .map(result =>
      result.check_type
    );

const assessmentCycle =
  normalisedResults.length > 0
    ? 'RESUMED'
    : 'INITIAL';

return [
  {
    json: {
      chat_input:
        request.chat_input,

      case_run_id:
        request.case_run_id,

      submission_version:
        Number(
          request.submission_version || 1
        ),

      processing_mode:
        'MOCK',

      persist_results:
        true,

      session_id:
        request.session_id || '',

      assessment_cycle:
        assessmentCycle,

      reassessment_mode:
        assessmentCycle === 'RESUMED',

      next_required_check:
        nextRequiredCheck,

      completed_mandatory_checks:
        completedMandatoryChecks,

      pending_mandatory_checks:
        pendingMandatoryChecks,

      evidence_resolved_checks:
        evidenceResolvedChecks,

      case_context: {
        case_run_id:
          caseRow.Case_Run_ID,

        logical_case_id:
          caseRow.Case_ID,

        submission_version:
          Number(
            caseRow.Submission_Version
          ),

        country:
          caseRow.Country,

        request_type:
          caseRow.Request_Type,

        business_name:
          caseRow.Business_Name_Submitted,

        business_identifier:
          caseRow.Business_Identifier_Submitted,

        customer_id:
          caseRow.Customer_ID,

        representative_name:
          caseRow.Representative_Name,

        representative_role:
          caseRow.Representative_Role,

        requested_authority:
          caseRow.Requested_Authority,

        request_narrative:
          caseRow.Customer_Request_Narrative,

        documents_submitted:
          caseRow.Documents_Submitted,
      },

      existing_runtime_results:
        normalisedResults,

      prototype_data:
        true,
    },
  },
];

