parameters.jsCode:
const chainResult =
  $json || {};

let parsingInput;

try {
  parsingInput =
    $('Prepare Parsing Input')
      .item
      .json;
} catch {
  const sameRunItems =
    $('Prepare Parsing Input')
      .all(
        0,
        $runIndex
      );

  parsingInput =
    sameRunItems[0]?.json;
}

if (!parsingInput) {
  throw new Error(
    'Could not resolve the current parsing input.'
  );
}

let provisional =
  chainResult.output ??
  chainResult.text ??
  chainResult.response ??
  chainResult;

if (
  provisional &&
  typeof provisional ===
    'object' &&
  !Array.isArray(provisional) &&
  provisional.output !== undefined
) {
  provisional =
    provisional.output;
}

if (
  typeof provisional ===
  'string'
) {
  const cleaned =
    provisional
      .trim()
      .replace(
        /^```json\s*/i,
        ''
      )
      .replace(
        /^```\s*/i,
        ''
      )
      .replace(
        /\s*```$/i,
        ''
      );

  provisional =
    JSON.parse(cleaned);
}

const allowedOutcomes = [
  'APPROVE',
  'REJECT',
  'NEED_MORE_INFORMATION',
  'MANUAL_REVIEW',
];

let provisionalOutcome =
  String(
    provisional
      .provisional_outcome ||
    ''
  )
    .trim()
    .toUpperCase()
    .replace(
      /\s+/g,
      '_'
    );

if (
  !allowedOutcomes.includes(
    provisionalOutcome
  )
) {
  provisionalOutcome =
    'MANUAL_REVIEW';
}

function stringArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(item =>
      typeof item === 'string'
        ? item.trim()
        : JSON.stringify(item)
    )
    .filter(Boolean);
}

const rawConfidence =
  Number(
    provisional.confidence
  );

const confidence =
  Number.isFinite(rawConfidence)
    ? Math.max(
        0,
        Math.min(
          1,
          rawConfidence
        )
      )
    : 0;

return [
  {
    json: {
      case_run_id:
        parsingInput.case_run_id,

      submission_version:
        parsingInput.submission_version,

      assessment_cycle:
        parsingInput.assessment_cycle,

      provisional_recommendation: {
        case_run_id:
          parsingInput.case_run_id,

        tools_called:
          stringArray(
            provisional.tools_called
          ),

        provisional_outcome:
          provisionalOutcome,

        evidence_summary:
          stringArray(
            provisional
              .evidence_summary
          ),

        missing_information:
          stringArray(
            provisional
              .missing_information
          ),

        conflicts:
          stringArray(
            provisional.conflicts
          ),

        human_review_required:
          provisional
            .human_review_required ===
            true ||
          provisionalOutcome ===
            'MANUAL_REVIEW',

        next_action:
          String(
            provisional.next_action ||
            ''
          ),

        decision_rationale:
          String(
            provisional
              .decision_rationale ||
            ''
          ),

        confidence,
      },

      intermediate_steps:
        parsingInput
          .compact_intermediate_steps,
    },
  },
];

/*
============================================================
BUILD CHAT RESPONSE
============================================================

Purpose:
- Create one clean, client-facing response.
- Never expose raw prompts, tool JSON, rule objects, or debug data.
- De-duplicate completed checks by check_type.
- Supplement missing check names from the visible tool trace without
  falsely claiming that an unknown check passed.
- Translate technical queue/reason codes into readable language.
============================================================
*/

const result =
  $input.first()?.json || {};

/*
------------------------------------------------------------
HELPER FUNCTIONS
------------------------------------------------------------
*/

function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}

function toBoolean(value) {
  return (
    value === true ||
    String(value)
      .trim()
      .toLowerCase() === 'true' ||
    String(value)
      .trim()
      .toUpperCase() === 'YES'
  );
}

function normaliseList(value) {
  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return [];
  }

  if (Array.isArray(value)) {
    return value;
  }

  if (typeof value === 'object') {
    return [value];
  }

  const text =
    String(value).trim();

  if (!text) {
    return [];
  }

  /*
  Support JSON-array strings.
  */
  if (
    text.startsWith('[') &&
    text.endsWith(']')
  ) {
    try {
      const parsed =
        JSON.parse(text);

      if (Array.isArray(parsed)) {
        return parsed;
      }
    } catch {
      // Fall through to delimiter parsing.
    }
  }

  return text
    .split(/\s*;\s*|\r?\n+/)
    .map(item => item.trim())
    .filter(Boolean);
}

function uniqueStrings(values) {
  const output = [];
  const seen = new Set();

  for (const value of values) {
    const text =
      String(value || '').trim();

    if (!text) {
      continue;
    }

    const key =
      text.toUpperCase();

    if (!seen.has(key)) {
      seen.add(key);
      output.push(text);
    }
  }

  return output;
}

function titleCaseCode(value) {
  return String(value || '')
    .trim()
    .replace(/_/g, ' ')
    .toLowerCase()
    .replace(
      /\b\w/g,
      character =>
        character.toUpperCase()
    );
}

function timestamp(value) {
  const parsed =
    Date.parse(
      String(value || '')
    );

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}

/*
Convert either a check code or a Workflow Tool name into the
canonical check_type used by the decision model.
*/
function canonicalCheckType(value) {
  let rawValue = value;

  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    rawValue =
      firstNonEmpty(
        value.check_type,
        value.Check_Type,
        value.tool,
        value.tool_name,
        value.toolName,
        value.name,
        value.utility_name,
        value.Utility_Name
      );
  }

  const upper =
    String(rawValue || '')
      .trim()
      .toUpperCase()
      .replace(/[\s-]+/g, '_');

  if (!upper) {
    return '';
  }

  if (
    upper.includes(
      'DOCUMENT'
    )
  ) {
    return 'DOCUMENT_EXTRACTION';
  }

  if (
    upper.includes(
      'BUSINESS'
    )
  ) {
    return 'BUSINESS_VALIDATION';
  }

  if (
    upper.includes(
      'IDENTITY'
    )
  ) {
    return 'IDENTITY_VALIDATION';
  }

  if (
    upper.includes(
      'AUTHORITY'
    )
  ) {
    return 'AUTHORITY_VALIDATION';
  }

  if (
    upper.includes(
      'SYSTEM'
    ) ||
    upper.includes(
      'CRM'
    ) ||
    upper.includes(
      'PARTY_DATA'
    )
  ) {
    return 'SYSTEM_DATA_CHECK';
  }

  if (
    upper.includes(
      'FINANCIAL'
    ) ||
    upper.includes(
      'CREDIT'
    ) ||
    upper.includes(
      'BAD_DEBT'
    )
  ) {
    return 'FINANCIAL_CHECK';
  }

  if (
    upper.includes(
      'FINAL'
    ) ||
    upper.includes(
      'COMPLIANCE'
    ) ||
    upper.includes(
      'AVCV'
    )
  ) {
    return 'FINAL_VERIFICATION';
  }

  return upper;
}

/*
------------------------------------------------------------
DISPLAY CONFIGURATION
------------------------------------------------------------
*/

const checkNameMap = {
  DOCUMENT_EXTRACTION:
    'Document checks',

  BUSINESS_VALIDATION:
    'Business validation',

  IDENTITY_VALIDATION:
    'Identity validation',

  AUTHORITY_VALIDATION:
    'Authority validation',

  SYSTEM_DATA_CHECK:
    'System-data checks',

  FINANCIAL_CHECK:
    'Financial checks',

  FINAL_VERIFICATION:
    'Final verification',
};

const checkSequenceMap = {
  DOCUMENT_EXTRACTION: 1,
  BUSINESS_VALIDATION: 2,
  IDENTITY_VALIDATION: 3,
  AUTHORITY_VALIDATION: 4,
  SYSTEM_DATA_CHECK: 5,
  FINANCIAL_CHECK: 6,
  FINAL_VERIFICATION: 7,
};

const statusMeta = {
  PASS: {
    icon: '✓',
    label: 'Passed',
    rank: 2,
  },

  PASS_WITH_FLAG: {
    icon: '△',
    label: 'Passed with a flag',
    rank: 3,
  },

  INCONCLUSIVE: {
    icon: '⚠',
    label: 'Issue identified',
    rank: 4,
  },

  FAIL: {
    icon: '✕',
    label: 'Failed',
    rank: 5,
  },

  EXECUTED: {
    icon: '•',
    label: 'Executed',
    rank: 1,
  },

  NOT_RUN: {
    icon: '–',
    label: 'Not run',
    rank: 0,
  },
};

const outcomeMeta = {
  APPROVE: {
    icon: '✅',
    title:
      'Eligible to proceed',
    label:
      'APPROVE',
  },

  NEED_MORE_INFORMATION: {
    icon: '📄',
    title:
      'Additional evidence required',
    label:
      'NEED MORE INFORMATION',
  },

  MANUAL_REVIEW: {
    icon: '👤',
    title:
      'Specialist review required',
    label:
      'MANUAL REVIEW',
  },

  REJECT: {
    icon: '⛔',
    title:
      'Unable to proceed',
    label:
      'REJECT',
  },
};

const reasonTextMap = {
  ALL_CHECKS_PASSED:
    'All mandatory checks completed successfully.',

  DOCUMENT_MISSING:
    'One or more required documents have not been supplied.',

  DOCUMENT_UNREADABLE:
    'A submitted document cannot be read reliably.',

  DOCUMENT_CONTRADICTION:
    'The submitted documents contain information that requires clarification.',

  BUSINESS_INACTIVE:
    'The business-registration status does not support automated progression.',

  REGISTRY_UNAVAILABLE:
    'The business-register result is unavailable and requires specialist review.',

  IDENTITY_MISMATCH:
    'The submitted identity information does not align with the case details.',

  AUTHORITY_MISSING:
    'The required authority evidence has not been supplied.',

  AUTHORITY_SCOPE_INSUFFICIENT:
    'The submitted authority does not cover every requested permission.',

  AUTHORITY_SCOPE_AMBIGUOUS:
    'The submitted authority does not clearly establish every requested permission.',

  DUPLICATE_RECORD_CONFLICT:
    'Conflicting customer or party records require reconciliation.',

  ADDITIONAL_EVIDENCE_ACCEPTED:
    'The additional evidence resolved the identified gap.',

  ADDITIONAL_EVIDENCE_INSUFFICIENT:
    'The additional evidence does not yet resolve the identified gap.',

  ADDITIONAL_EVIDENCE_CONTRADICTORY:
    'The new evidence conflicts with previously validated case information.',

  PROMPT_INJECTION_DETECTED:
    'A submitted document requires specialist security review.',

  TBD_POLICY:
    'The case requires review by the relevant policy owner.',

  FINAL_VERIFICATION_FAILED:
    'The final required verification did not complete successfully.',

  CUSTOMER_CONFIRMATION_REQUIRED:
    'Customer confirmation is required before the case can continue.',

  SALES_CONFIRMATION_REQUIRED:
    'Sales or account-team confirmation is required before the case can continue.',

  AGENT_TOOL_RESULTS_MISSING:
    'The automated assessment could not be completed and requires operational review.',

  MANDATORY_CHECKS_INCOMPLETE:
    'One or more mandatory validation checks remain incomplete.',
};

const queueLabelMap = {
  ORDER_READINESS:
    'Order Readiness',

  AUTHORITY_REVIEW:
    'Authority Review',

  DATA_RECONCILIATION:
    'Customer Data Reconciliation',

  SECURITY_REVIEW:
    'Security Review',

  POLICY_REVIEW:
    'Policy Review',

  EVIDENCE_REVIEW:
    'Evidence Review',

  AGENT_OPERATIONS_REVIEW:
    'Agent Operations Review',

  CUSTOMER_FOLLOW_UP:
    'Customer Follow-up',

  SBO_02:
    'Profiling Operations',
};

/*
------------------------------------------------------------
CORE CASE FIELDS
------------------------------------------------------------
*/

const caseRunId =
  String(
    firstNonEmpty(
      result.case_run_id,
      result.Case_Run_ID
    )
  ).trim();

const businessName =
  String(
    firstNonEmpty(
      result.business_name,
      result.Business_Name,
      'Business not recorded'
    )
  ).trim();

const representativeName =
  String(
    firstNonEmpty(
      result.representative_name,
      result.Representative_Name,
      'Representative not recorded'
    )
  ).trim();

const outcome =
  String(
    firstNonEmpty(
      result.governed_outcome,
      result.outcome,
      'MANUAL_REVIEW'
    )
  )
    .trim()
    .toUpperCase();

const primaryReasonCode =
  String(
    firstNonEmpty(
      result.primary_reason_code,
      result.Primary_Reason_Code
    )
  )
    .trim()
    .toUpperCase();

const targetQueue =
  String(
    firstNonEmpty(
      result.target_queue,
      result.Target_Queue
    )
  )
    .trim()
    .toUpperCase();

const nextAction =
  String(
    firstNonEmpty(
      result.next_action,
      result.Next_Action,
      'Await the next operational step.'
    )
  ).trim();

const humanReviewRequired =
  toBoolean(
    firstNonEmpty(
      result.human_review_required,
      result.Human_Review_Required
    )
  );

const outcomeDisplay =
  outcomeMeta[outcome] ||
  outcomeMeta.MANUAL_REVIEW;

/*
------------------------------------------------------------
NORMALISE AND DE-DUPLICATE COMPLETED CHECKS
------------------------------------------------------------
*/

const rawCompletedChecks =
  normaliseList(
    result.completed_checks
  );

function normaliseCheck(
  rawCheck,
  fallbackIndex
) {
  if (
    rawCheck === undefined ||
    rawCheck === null
  ) {
    return null;
  }

  if (
    typeof rawCheck === 'string'
  ) {
    const checkType =
      canonicalCheckType(
        rawCheck
      );

    if (!checkType) {
      return null;
    }

    return {
      check_type:
        checkType,

      status:
        'EXECUTED',

      sequence:
        checkSequenceMap[
          checkType
        ] ??
        fallbackIndex,

      rule_ids:
        [],

      reason_codes:
        [],

      created_at:
        '',
    };
  }

  const checkType =
    canonicalCheckType(
      rawCheck
    );

  if (!checkType) {
    return null;
  }

  const status =
    String(
      firstNonEmpty(
        rawCheck.status,
        rawCheck.Status,
        'EXECUTED'
      )
    )
      .trim()
      .toUpperCase();

  return {
    ...rawCheck,

    check_type:
      checkType,

    status,

    sequence:
      Number(
        firstNonEmpty(
          rawCheck.sequence,
          rawCheck.Sequence,
          checkSequenceMap[
            checkType
          ],
          fallbackIndex
        )
      ),

    rule_ids:
      normaliseList(
        firstNonEmpty(
          rawCheck.rule_ids,
          rawCheck.Rule_IDs
        )
      ).map(item =>
        String(item).trim()
      ),

    reason_codes:
      normaliseList(
        firstNonEmpty(
          rawCheck.reason_codes,
          rawCheck.Reason_Codes
        )
      ).map(item =>
        String(item).trim()
      ),

    created_at:
      String(
        firstNonEmpty(
          rawCheck.created_at,
          rawCheck.Created_At
        )
      ).trim(),
  };
}

function shouldReplaceCheck(
  existing,
  candidate
) {
  const existingHasEvidencePass =
    existing.rule_ids.includes(
      'EVID-001'
    );

  const candidateHasEvidencePass =
    candidate.rule_ids.includes(
      'EVID-001'
    );

  /*
  An accepted-evidence PASS must replace an earlier
  inconclusive result for the same check.
  */
  if (
    candidateHasEvidencePass &&
    !existingHasEvidencePass
  ) {
    return true;
  }

  if (
    existingHasEvidencePass &&
    !candidateHasEvidencePass
  ) {
    return false;
  }

  const existingTime =
    timestamp(
      existing.created_at
    );

  const candidateTime =
    timestamp(
      candidate.created_at
    );

  if (
    candidateTime !==
    existingTime
  ) {
    return (
      candidateTime >
      existingTime
    );
  }

  const existingRank =
    statusMeta[
      existing.status
    ]?.rank ?? 0;

  const candidateRank =
    statusMeta[
      candidate.status
    ]?.rank ?? 0;

  /*
  If timestamps aren't available, retain the more
  consequential status. For exact duplicates, the
  later candidate replaces the earlier one.
  */
  return (
    candidateRank >=
    existingRank
  );
}

const completedChecksByType =
  new Map();

rawCompletedChecks.forEach(
  (rawCheck, index) => {
    const normalisedCheck =
      normaliseCheck(
        rawCheck,
        index + 1
      );

    if (!normalisedCheck) {
      return;
    }

    const existing =
      completedChecksByType.get(
        normalisedCheck.check_type
      );

    if (
      !existing ||
      shouldReplaceCheck(
        existing,
        normalisedCheck
      )
    ) {
      completedChecksByType.set(
        normalisedCheck.check_type,
        normalisedCheck
      );
    }
  }
);

/*
------------------------------------------------------------
SUPPLEMENT THE VALIDATION PATH FROM THE AGENT TOOL TRACE
------------------------------------------------------------

This is a defensive presentation fallback.

If Workflow 90 supplies only one malformed repeated check but the
Agent trace confirms that other tools were called, show those other
checks as "Executed".

Do not mark trace-only checks as Passed because the trace alone does
not establish their result.
------------------------------------------------------------
*/

const traceSources = [
  result.visible_tool_trace,
  result.tools_called,
  result.provisional_recommendation
    ?.tools_called,
];

const rawTraceItems =
  traceSources.flatMap(
    source =>
      normaliseList(
        source
      )
  );

for (
  let index = 0;
  index < rawTraceItems.length;
  index += 1
) {
  const traceItem =
    rawTraceItems[index];

  const checkType =
    canonicalCheckType(
      traceItem
    );

  if (!checkType) {
    continue;
  }

  if (
    !completedChecksByType.has(
      checkType
    )
  ) {
    completedChecksByType.set(
      checkType,
      {
        check_type:
          checkType,

        status:
          'EXECUTED',

        sequence:
          checkSequenceMap[
            checkType
          ] ??
          index + 1,

        rule_ids:
          [],

        reason_codes:
          [],

        created_at:
          '',
      }
    );
  }
}

const completedChecks =
  Array.from(
    completedChecksByType.values()
  )
    .sort(
      (a, b) =>
        Number(a.sequence) -
        Number(b.sequence)
    );

const completedCheckLines =
  completedChecks.map(
    check => {
      const display =
        statusMeta[
          check.status
        ] || {
          icon:
            '•',

          label:
            titleCaseCode(
