      const displayName =
        checkNameMap[
          check.check_type
        ] ||
        titleCaseCode(
          check.check_type
        );

      return (
        `- ${display.icon} ` +
        `${displayName} — ` +
        `${display.label}`
      );
    }
  );

/*
------------------------------------------------------------
