      .map(item =>
        `- ${item}`
      )
      .join('\n')
  );
}

/*
Do not clutter an internal orchestration failure with a list
of all checks that never started.
*/
if (
  deferredChecks.length > 0 &&
  primaryReasonCode !==
    'AGENT_TOOL_RESULTS_MISSING'
