);

sections.push(
  `---\n` +
  `*Synthetic prototype. No production-system update or customer communication has been performed.*`
);

/*
------------------------------------------------------------
RETURN THE CURATED CHAT RESPONSE
------------------------------------------------------------
*/

return [
  {
    json: {
