function extractResponse(input) {
  const candidates = [
    input.response,
    input.text,
    input.chatInput,
    input.message,
    input.answer,
    input.data?.response,
    input.data?.text,
    input.data?.message,
    input.data,
  ];

  for (const candidate of candidates) {
    if (
      candidate !== undefined &&
      candidate !== null
    ) {
      if (typeof candidate === 'string') {
        return candidate.trim();
      }

      if (typeof candidate === 'object') {
        const nested =
          candidate.response ??
          candidate.text ??
          candidate.message ??
          candidate.answer;

        if (typeof nested === 'string') {
          return nested.trim();
        }
      }
    }
  }

  return '';
}

const response =
  extractResponse($json || {});

const upper =
  response.toUpperCase();

const request =
  $('Create Evidence Request')
    .last()
    .json;

return [
  {
    json: {
      evidence_request_id:
        request.evidence_request_id,

      case_run_id:
        request.case_run_id,

      submission_version:
        Number(
          request.submission_version || 1
        ),

      originating_check_type:
        request.originating_check_type,

      evidence_channel:
        request.evidence_channel,

      evidence_text:
        response,

      customer_cancelled:
        [
          'CANCEL',
          'STOP',
          'END',
          'CANCEL REQUEST',
        ].includes(upper),

      evidence_received:
        response.length > 0,
    },
  },
];

/*
============================================================
BUILD EVIDENCE UPLOAD LINK
============================================================

Creates a production-form URL containing:
- evidence_request_id
- case_run_id

Do not manually escape the ampersand.
============================================================
*/

const request =
  $('Create Evidence Request')
    .last()
    .json || {};

const formProductionUrl =
  'https://pocagents.app.n8n.cloud/form/submit-case-evidence';

const evidenceRequestId =
  String(
    request.evidence_request_id || ''
  ).trim();

const caseRunId =
  String(
    request.case_run_id || ''
  ).trim();

if (!evidenceRequestId) {
  throw new Error(
    'Cannot build upload URL: evidence_request_id is missing.'
  );
}

if (!caseRunId) {
