          .assessment_cycle,

      provisional_recommendation:
        provisional,

      provisional_outcome:
        provisionalOutcome,

      governed_outcome:
        governedOutcome,

      governance_override:
        governanceOverride,

      governance_override_message:
        governanceOverride
          ? (
              `The AI Agent recommended ${provisionalOutcome}, ` +
              `but deterministic policy recorded ${governedOutcome}.`
            )
          : (
              'The AI Agent recommendation and deterministic policy outcome are aligned.'
            ),

      visible_tool_trace:
        provisional
          .tools_called || [],

      provisional_rationale:
        provisional
