  $('Get Mock Utility Result').first().json;

const rules = $('Get Decision Rules')
  .all()
  .map(item => item.json);

function splitSemi(value) {
  if (!value) {
    return [];
  }

  return String(value)
    .split(';')
    .map(value => value.trim())
    .filter(Boolean);
}

function safeParse(value) {
  try {
    return value ? JSON.parse(value) : {};
  } catch (error) {
    return {
      parse_error: true,
      raw_value: value,
    };
  }
}

function toBoolean(value) {
  return value === true ||
    String(value).toLowerCase() === 'true';
}

const ruleIds = splitSemi(row.Rule_IDs);

const applicableRules = rules
  .filter(rule => ruleIds.includes(rule.Rule_ID))
  .sort(
    (a, b) =>
      Number(a.Priority ?? 9999) -
      Number(b.Priority ?? 9999)
  );

const hasTbd = applicableRules.some(
  rule =>
    String(rule.Rule_Status).toUpperCase() ===
    'TBD'
);

let appliedRule = null;

if (hasTbd) {
  appliedRule = rules.find(
    rule => rule.Rule_ID === 'CTRL-001'
  );
} else {
  appliedRule =
    applicableRules.find(rule =>
      [
        'REJECT',
        'NEED_MORE_INFORMATION',
        'MANUAL_REVIEW',
      ].includes(
        String(rule.Final_Outcome).toUpperCase()
      )
    ) ||
    applicableRules[0] ||
    null;
}

const terminalOutcome =
  appliedRule?.Final_Outcome || 'CONTINUE';

return [
  {
    json: {
      case_run_id: row.Case_Run_ID,
      submission_version: 1,
      sequence: Number(row.Sequence),
      agent_id: row.Agent_ID,
      utility_name: row.Utility_Name,
      check_type: row.Check_Type,
      status: row.Status,
      findings: safeParse(row.Findings_JSON),
      reason_codes: splitSemi(row.Reason_Codes),
      evidence_references: splitSemi(
        row.Evidence_References
      ),
      confidence: Number(row.Confidence || 0),
      human_review_required: toBoolean(
        row.Human_Review_Required
      ),
      recommended_next_step:
        row.Recommended_Next_Step,
      rule_ids: ruleIds,
      rule_status_used: row.Rule_Status_Used,
      applied_rule: appliedRule,
      is_terminal: [
        'REJECT',
        'NEED_MORE_INFORMATION',
        'MANUAL_REVIEW',
      ].includes(
        String(terminalOutcome).toUpperCase()
      ),
      terminal_outcome: terminalOutcome,
      prototype_data: true,
    },
  },
];

return [
  {
    json:
      $('Build Utility Result').first().json,
  },
];

