    Array.isArray(decision.missing_information) &&
    decision.missing_information.length > 0
      ? decision.missing_information.join(', ')
      : 'None',
};

function fillTemplate(text = '') {
  return String(text).replace(
    /\{(\w+)\}/g,
    (match, key) =>
      values[key] !== undefined
        ? String(values[key])
        : match
  );
}

return [{
  json: {
    ...decision,

    communication: {
      template_id:
        template.Template_ID,

      audience:
        template.Audience,

      subject:
        fillTemplate(
          template.Subject_Template
        ),

      body:
        fillTemplate(
          template.Body_Template
        ),

      status:
        'DRAFT',

      approval_required:
        true,

      sent:
        false,
    },
  },
}];

const caseRow =
  $('Get Case').first().json;

const resultSource =
  $('Prepare Result Source')
    .first()
    .json
    .result_source;

let utilityRows = [];

if (resultSource === 'RUNTIME') {
  utilityRows =
    $('Package Runtime Utility Results')
      .first()
      .json
      .utility_rows || [];
} else {
  utilityRows =
    $('Package Mock Utility Results')
      .first()
      .json
      .utility_rows || [];
}

const ruleRows =
  $('Get Decision Rules')
    .all()
    .map(item => item.json);

function splitSemi(value) {
  if (
    value === undefined ||
    value === null ||
    value === ''
  ) {
    return [];
  }

  return String(value)
    .split(';')
    .map(value => value.trim())
    .filter(Boolean);
}

function safeParse(value) {
  if (!value) {
    return {};
  }

  if (typeof value === 'object') {
    return value;
  }

  try {
    return JSON.parse(value);
  } catch {
    return {
      parse_error: true,
      raw_value: String(value)
    };
  }
}

function toBoolean(value) {
  return (
    value === true ||
    String(value).toLowerCase() === 'true' ||
    String(value).toUpperCase() === 'YES'
  );
}

const rulesById =
  Object.fromEntries(
    ruleRows.map(rule => [
      String(rule.Rule_ID).trim(),
      rule
    ])
  );

const checks =
  utilityRows.map(row => ({
    sequence:
      Number(row.Sequence || 0),

    agent_id:
      row.Agent_ID,

    utility_name:
      row.Utility_Name,

    check_type:
      row.Check_Type,

    status:
      row.Status,

    findings:
      safeParse(row.Findings_JSON),

    reason_codes:
      splitSemi(row.Reason_Codes),

    evidence_references:
      splitSemi(row.Evidence_References),

    confidence:
      Number(row.Confidence || 0),

    human_review_required:
      toBoolean(
        row.Human_Review_Required
      ),

    recommended_next_step:
      row.Recommended_Next_Step,

    rule_ids:
      splitSemi(row.Rule_IDs),

    rule_status_used:
      row.Rule_Status_Used
  }));

const requiredChecks = [
  'DOCUMENT_EXTRACTION',
  'BUSINESS_VALIDATION',
  'IDENTITY_VALIDATION',
  'AUTHORITY_VALIDATION',
  'SYSTEM_DATA_CHECK',
  'FINANCIAL_CHECK',
  'FINAL_VERIFICATION'
];

const observedCompletedCheckTypes =
  new Set(
    checks
      .filter(check =>
        String(check.status).toUpperCase() !==
        'NOT_RUN'
      )
      .map(check => check.check_type)
  );

const explicitNotRun =
  checks
    .filter(check =>
      String(check.status).toUpperCase() ===
      'NOT_RUN'
    )
    .map(check => check.check_type);

const absentMandatoryChecks =
  requiredChecks.filter(
    checkType =>
      !observedCompletedCheckTypes.has(
        checkType
      )
  );

const referencedRuleIds = [
  ...new Set(
    checks.flatMap(
      check => check.rule_ids
    )
  )
];

const applicableRules =
  referencedRuleIds
    .map(ruleId => rulesById[ruleId])
    .filter(Boolean)
    .sort(
      (a, b) =>
        Number(a.Priority ?? 9999) -
        Number(b.Priority ?? 9999)
    );

const tbdRule =
  applicableRules.find(
    rule =>
      String(rule.Rule_Status)
        .toUpperCase() ===
      'TBD'
  );

let selectedRule = null;
let governanceControlApplied = false;

if (
  resultSource === 'RUNTIME' &&
  checks.length === 0
) {
  selectedRule =
    rulesById['CTRL-002'];

  governanceControlApplied = true;

  if (!selectedRule) {
    throw new Error(
      'CTRL-002 is missing from dt_decision_rules.'
    );
  }
} else if (tbdRule) {
  selectedRule =
    rulesById['CTRL-001'];

  governanceControlApplied = true;

  if (!selectedRule) {
    throw new Error(
      'CTRL-001 is missing from dt_decision_rules.'
    );
  }
} else {
  selectedRule =
    applicableRules.find(rule =>
      [
        'REJECT',
        'NEED_MORE_INFORMATION',
        'MANUAL_REVIEW'
      ].includes(
        String(
          rule.Final_Outcome
        ).toUpperCase()
      )
    ) || null;
}

if (!selectedRule) {
  if (
    resultSource === 'RUNTIME' &&
    absentMandatoryChecks.length > 0
  ) {
    selectedRule =
      rulesById['CTRL-003'];

    governanceControlApplied = true;

    if (!selectedRule) {
      throw new Error(
        'CTRL-003 is missing from dt_decision_rules.'
      );
    }
  } else {
    const successfulChecks =
      new Set(
        checks
          .filter(check =>
            [
              'PASS',
              'PASS_WITH_FLAG'
            ].includes(
              String(check.status)
                .toUpperCase()
            )
          )
          .map(check =>
            check.check_type
          )
      );

    const failedCompleteness =
      requiredChecks.filter(
        checkType =>
          !successfulChecks.has(
            checkType
          )
      );

    if (
      failedCompleteness.length > 0
    ) {
      throw new Error(
        `Approval blocked. Mandatory checks incomplete: ${failedCompleteness.join(', ')}`
      );
    }

    selectedRule =
      rulesById['FINAL-001'];

    if (!selectedRule) {
      throw new Error(
        'FINAL-001 is missing from dt_decision_rules.'
      );
    }
  }
}

const outcome =
  String(
    selectedRule.Final_Outcome
  ).toUpperCase();

const missingInformation = [];

for (const check of checks) {
  const missing =
    check.findings?.missing;

  if (Array.isArray(missing)) {
    missingInformation.push(
      ...missing
    );
  }
}

if (
  applicableRules.some(
    rule =>
      rule.Reason_Code ===
      'AUTHORITY_MISSING'
  ) &&
  !missingInformation.includes(
    'AUTHORITY_LETTER'
  )
) {
  missingInformation.push(
    'AUTHORITY_LETTER'
  );
}

const conflicts = [];

for (const check of checks) {
  const findings =
    check.findings || {};

  if (
    findings.legal_name_conflict ===
    true
  ) {
    conflicts.push(
      'Conflicting legal names exist across CRM records.'
    );
  }

  if (
    findings.open_duplicate_request ===
    true
  ) {
    conflicts.push(
      'Another authority request is already open.'
    );
  }

  if (
    String(findings.scope)
      .toUpperCase() ===
    'AMBIGUOUS'
  ) {
    conflicts.push(
      'The submitted authority scope is ambiguous.'
    );
  }

  if (
    findings.security_flag &&
    String(findings.security_flag)
      .toUpperCase() !==
    'NONE'
  ) {
    conflicts.push(
      'A document security flag requires specialist review.'
    );
  }

  if (
    String(findings.lookup_status)
      .toUpperCase() ===
    'UNAVAILABLE'
  ) {
    conflicts.push(
      'The business-register lookup is unavailable.'
    );
  }
}

const allReasonCodes = [
  ...new Set(
    checks.flatMap(
      check => check.reason_codes
    )
  )
];

const assumptionsUsed =
  applicableRules
    .filter(
      rule =>
        String(rule.Rule_Status)
          .toUpperCase() ===
        'ASSUMPTION'
    )
    .map(rule => rule.Rule_ID);

const checksNotRun = [
  ...new Set([
    ...explicitNotRun,
    ...(resultSource === 'RUNTIME'
      ? absentMandatoryChecks
      : [])
  ])
];

let customerSafeSummary;

switch (outcome) {
  case 'APPROVE':
    customerSafeSummary =
      'The prototype assessment completed all mandatory checks successfully. The request is eligible to proceed to the next operational step.';
    break;

  case 'NEED_MORE_INFORMATION':
    customerSafeSummary =
      'The assessment cannot be completed until the requested information is supplied.';
    break;

  case 'MANUAL_REVIEW':
    customerSafeSummary =
      'The assessment identified information that requires review by an operations specialist. No final adverse decision has been made.';
    break;

  case 'REJECT':
    customerSafeSummary =
      'The prototype identified a condition that prevents automated progression. Human confirmation is required before final disposition.';
    break;

  default:
    customerSafeSummary =
      'The assessment requires further processing.';
}

const decision = {
  case_run_id:
    caseRow.Case_Run_ID,

  case_id:
    caseRow.Case_ID,

  submission_version:
    Number(
      caseRow.Submission_Version
    ),

  country:
    caseRow.Country,

  request_type:
    caseRow.Request_Type,

  business_name:
    caseRow.Business_Name_Submitted,

  business_identifier:
    caseRow.Business_Identifier_Submitted,

  customer_id:
    caseRow.Customer_ID,

  representative_name:
    caseRow.Representative_Name,

  result_source:
    resultSource,

  outcome,

  primary_reason_code:
    selectedRule.Reason_Code,

  secondary_reason_codes:
    allReasonCodes,

  human_review_required:
    toBoolean(
      selectedRule
        .Human_Review_Required
    ),

  target_queue:
    selectedRule.Target_Queue,

  next_action:
    selectedRule.Next_Action,

  communication_template_id:
    selectedRule
      .Communication_Template_ID,

  applied_rule_id:
    selectedRule.Rule_ID,

  applied_rule_status:
    selectedRule.Rule_Status,

  governance_control_applied:
    governanceControlApplied,

  triggering_tbd_rule:
    tbdRule
      ? tbdRule.Rule_ID
      : null,

  missing_information: [
    ...new Set(
      missingInformation
    )
  ],

  conflicts: [
    ...new Set(conflicts)
  ],

  assumptions_used:
    assumptionsUsed,

  completed_checks:
    checks.filter(
      check =>
        String(check.status)
          .toUpperCase() !==
        'NOT_RUN'
    ),

  checks_not_run:
    checksNotRun,

  customer_safe_summary:
    customerSafeSummary,

  prototype_data:
    true,

  production_write_performed:
    false
};

return [
  {
    json: decision
  }
];

return [{
  json:
    $('Build Communication').first().json
}];

const rows = $input
  .all()
  .map(item => item.json)
  .filter(row =>
    String(row.Case_Run_ID || '').trim()
  );

return [
  {
    json: {
      result_source: 'MOCK',
      utility_rows: rows
    }
  }
];

/*
============================================================
PACKAGE RUNTIME UTILITY RESULTS
============================================================

Purpose:
- Read only the current input from Get Runtime Utility Results.
- Normalise runtime-table column names and data types.
- Filter to the requested case/version.
- Remove superseded rows.
- Keep one current row per check type.
- Preserve all seven mandatory checks.
- Produce diagnostic counts for troubleshooting.
============================================================
*/

const preparedSource =
  $('Prepare Result Source')
    .first()
    .json || {};

const expectedCaseRunId =
  String(
    preparedSource.case_run_id || ''
  ).trim();

const expectedSubmissionVersion =
  Number(
    preparedSource.submission_version || 1
  );

/*
------------------------------------------------------------
HELPERS
------------------------------------------------------------
*/

function pick(object, ...keys) {
  for (const key of keys) {
    const value =
      object?.[key];

    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}

function toBoolean(value) {
  return (
    value === true ||
    String(value)
      .trim()
      .toLowerCase() === 'true' ||
    String(value)
      .trim()
      .toUpperCase() === 'YES'
  );
}

function asTimestamp(value) {
  const parsed =
    Date.parse(
      String(value || '')
    );

  return Number.isFinite(parsed)
    ? parsed
    : 0;
}

/*
------------------------------------------------------------
READ CURRENT NODE INPUT ONLY
------------------------------------------------------------

The Package node must be connected directly after
Get Runtime Utility Results.

Do not replace $input.all() with:
- $('Get Decision Rules').all()
- $('Get Runtime Utility Results').first()
- $('Get Runtime Utility Results').item
*/

const sourceRows =
  $input
    .all()
    .map(
      (item, index) => ({
        ...(item.json || {}),

        __input_index:
          index,
      })
    );

/*
------------------------------------------------------------
NORMALISE RUNTIME ROWS
------------------------------------------------------------
*/

const normalisedRows =
  sourceRows
    .map(row => {
      const caseRunId =
        String(
          pick(
            row,
            'case_run_id',
            'Case_Run_ID'
          )
        ).trim();

      const submissionVersion =
        Number(
          pick(
            row,
            'submission_version',
            'Submission_Version'
          ) || 1
        );

      const checkType =
        String(
          pick(
            row,
            'check_type',
            'Check_Type'
          )
        )
          .trim()
          .toUpperCase();

      /*
      Ignore the empty placeholder that Always Output Data
      can emit when no row is found.
      */
      if (
        !caseRunId ||
        !checkType
      ) {
        return null;
      }

      return {
        Case_Run_ID:
          caseRunId,

        Submission_Version:
          submissionVersion,

        Sequence:
          Number(
            pick(
              row,
              'sequence',
              'Sequence'
            ) || 0
          ),

        Agent_ID:
          String(
            pick(
              row,
              'agent_id',
              'Agent_ID'
            )
          ).trim(),

        Utility_Name:
          String(
            pick(
              row,
              'utility_name',
              'Utility_Name'
            )
          ).trim(),

        Check_Type:
          checkType,

        Status:
          String(
            pick(
              row,
              'status',
              'Status'
            )
          )
            .trim()
            .toUpperCase(),

        Findings_JSON:
          pick(
            row,
            'findings_json',
            'Findings_JSON'
          ),

        Reason_Codes:
          String(
            pick(
              row,
              'reason_codes',
              'Reason_Codes'
            )
          ).trim(),

        Evidence_References:
          String(
            pick(
              row,
              'evidence_references',
              'Evidence_References'
            )
          ).trim(),

        Confidence:
          Number(
            pick(
              row,
              'confidence',
              'Confidence'
            ) || 0
          ),

        Human_Review_Required:
          toBoolean(
            pick(
              row,
              'human_review_required',
              'Human_Review_Required'
            )
          ),

        Recommended_Next_Step:
          String(
            pick(
              row,
              'recommended_next_step',
              'Recommended_Next_Step'
            )
          ).trim(),

        Rule_IDs:
          String(
            pick(
              row,
              'rule_ids',
              'Rule_IDs'
            )
          ).trim(),

        Rule_Status_Used:
          String(
            pick(
              row,
              'rule_status_used',
              'Rule_Status_Used'
            )
          ).trim(),

        Created_At:
          String(
            pick(
              row,
              'created_at',
              'Created_At',
              'createdAt'
            )
          ).trim(),

        Updated_At:
          String(
            pick(
              row,
              'updated_at',
              'Updated_At',
              'updatedAt'
            )
          ).trim(),

        Superseded:
          toBoolean(
            pick(
              row,
              'superseded',
              'Superseded'
            )
          ),

        __input_index:
          Number(
            row.__input_index || 0
          ),
      };
    })
    .filter(Boolean);

/*
------------------------------------------------------------
FILTER TO THE REQUESTED CASE/VERSION
------------------------------------------------------------
*/

const crossCaseRows =
  normalisedRows.filter(row =>
    row.Case_Run_ID !==
      expectedCaseRunId ||
    row.Submission_Version !==
      expectedSubmissionVersion
  );

const relevantRows =
  normalisedRows.filter(row =>
    row.Case_Run_ID ===
      expectedCaseRunId &&
    row.Submission_Version ===
      expectedSubmissionVersion &&
    row.Superseded !== true
  );

/*
------------------------------------------------------------
KEEP ONE CURRENT ROW PER CHECK TYPE
------------------------------------------------------------

Key:
case_run_id + submission_version + check_type

Where an unexpected duplicate exists:
1. prefer the most recently updated row;
2. then the most recently created row;
3. then the later incoming item.
*/

const rowsByCheckType =
  new Map();

for (const candidate of relevantRows) {
  const key =
    candidate.Check_Type;

  const existing =
    rowsByCheckType.get(key);

  if (!existing) {
    rowsByCheckType.set(
      key,
      candidate
    );

    continue;
  }

  const existingUpdatedAt =
    asTimestamp(
      existing.Updated_At
    );

  const candidateUpdatedAt =
    asTimestamp(
      candidate.Updated_At
    );

  const existingCreatedAt =
    asTimestamp(
      existing.Created_At
    );

  const candidateCreatedAt =
    asTimestamp(
      candidate.Created_At
    );

  const candidateIsLater =
    (
      candidateUpdatedAt >
      existingUpdatedAt
    ) ||
    (
      candidateUpdatedAt ===
        existingUpdatedAt &&
      candidateCreatedAt >
        existingCreatedAt
    ) ||
    (
      candidateUpdatedAt ===
        existingUpdatedAt &&
      candidateCreatedAt ===
        existingCreatedAt &&
      candidate.__input_index >
        existing.__input_index
    );

  if (candidateIsLater) {
    rowsByCheckType.set(
      key,
      candidate
    );
  }
}

const utilityRows =
  Array.from(
    rowsByCheckType.values()
  )
    .sort(
      (a, b) =>
        Number(a.Sequence) -
        Number(b.Sequence)
    )
    .map(row => ({
      Case_Run_ID:
        row.Case_Run_ID,

      Submission_Version:
        row.Submission_Version,

      Sequence:
        row.Sequence,

      Agent_ID:
        row.Agent_ID,

      Utility_Name:
        row.Utility_Name,

      Check_Type:
        row.Check_Type,

      Status:
        row.Status,

      Findings_JSON:
        row.Findings_JSON,

      Reason_Codes:
        row.Reason_Codes,

      Evidence_References:
        row.Evidence_References,

      Confidence:
        row.Confidence,

      Human_Review_Required:
        row.Human_Review_Required,

      Recommended_Next_Step:
        row.Recommended_Next_Step,

      Rule_IDs:
        row.Rule_IDs,

      Rule_Status_Used:
        row.Rule_Status_Used,
    }));

/*
------------------------------------------------------------
DIAGNOSTICS
------------------------------------------------------------
*/

const mandatoryChecks = [
  'DOCUMENT_EXTRACTION',
  'BUSINESS_VALIDATION',
  'IDENTITY_VALIDATION',
  'AUTHORITY_VALIDATION',
  'SYSTEM_DATA_CHECK',
  'FINANCIAL_CHECK',
  'FINAL_VERIFICATION',
];

const packagedCheckTypes =
  utilityRows.map(row =>
    row.Check_Type
  );

const packagedCheckTypeSet =
  new Set(
    packagedCheckTypes
  );

const missingMandatoryChecks =
  mandatoryChecks.filter(
    checkType =>
      !packagedCheckTypeSet.has(
        checkType
      )
  );

const duplicateRowsRemoved =
  Math.max(
    0,
    relevantRows.length -
      utilityRows.length
  );

/*
------------------------------------------------------------
RETURN ONE PACKAGE
------------------------------------------------------------
*/

return [
  {
    json: {
      result_source:
        'RUNTIME',

      expected_case_run_id:
        expectedCaseRunId,

      expected_submission_version:
        expectedSubmissionVersion,

      source_row_count:
        sourceRows.length,

      normalised_row_count:
        normalisedRows.length,

      relevant_active_row_count:
        relevantRows.length,

      runtime_row_count:
        utilityRows.length,

      duplicate_rows_removed:
        duplicateRowsRemoved,

      cross_case_row_count:
        crossCaseRows.length,

      packaged_check_types:
        packagedCheckTypes,

      missing_mandatory_checks:
        missingMandatoryChecks,

      utility_rows:
        utilityRows,
    },
  },
];

const review = $json || {};

const reviewId = String(
  review.review_id || ''
).trim();

const reviewStatus = String(
  review.review_status || ''
).toUpperCase();

const reviewFound = reviewId.length > 0;

const openStatuses = [
  'PENDING',
  'PENDING_REJECTION_CONFIRMATION',
];

const reviewOpen =
  reviewFound &&
  openStatuses.includes(reviewStatus);

return [
  {
    json: {
      ...review,
      review_found: reviewFound,
      review_open: reviewOpen,
      normalized_review_status: reviewStatus,
    },
  },
];

const form = $json;

const reviewPackage =
  $('Prepare Review Package').first().json;

const reviewerName = String(
  form.reviewer_name || ''
).trim();

const reviewerDecision = String(
  form.reviewer_decision || ''
).trim().toUpperCase();

const reviewerComments = String(
  form.reviewer_comments || ''
).trim();

const overrideReason = String(
  form.override_reason || ''
).trim();

const allowedDecisions = [
  'APPROVE',
  'NEED_MORE_INFORMATION',
  'REJECT',
];

if (!reviewerName) {
  throw new Error(
    'Reviewer name is required.'
  );
}

if (!allowedDecisions.includes(reviewerDecision)) {
  throw new Error(
    `Unsupported reviewer decision: ${reviewerDecision}`
  );
}

if (!reviewerComments) {
  throw new Error(
    'Reviewer comments are required.'
  );
}

const agentRecommendation = String(
  reviewPackage.agent_recommendation || ''
).toUpperCase();

// A rejection recommendation requires an override
// reason when the reviewer chooses another outcome.
if (
  agentRecommendation === 'REJECT' &&
  reviewerDecision !== 'REJECT' &&
  !overrideReason
) {
  throw new Error(
    'An override reason is required when changing a REJECT recommendation.'
  );
}

const outcomeConfiguration = {
  APPROVE: {
    target_queue:
      'ORDER_READINESS',

    next_action:
      'Proceed to the next controlled operational step. No production write-back has been performed.',

    communication_template_id:
      'TPL-APPROVE',

    customer_safe_summary:
      'A human reviewer approved the request after reviewing the available evidence.',
  },

  NEED_MORE_INFORMATION: {
    target_queue:
      'CUSTOMER_FOLLOW_UP',

    next_action:
      'Request the additional information identified by the reviewer and keep the case open.',

    communication_template_id:
      'TPL-NMI',

    customer_safe_summary:
      'A human reviewer determined that additional information is required before the assessment can be completed.',
  },

  REJECT: {
    target_queue:
      'CASE_CLOSURE',

    next_action:
      'Prepare the rejection communication for approval and close the synthetic case after the communication is confirmed.',

    communication_template_id:
      'TPL-REJECT',

    customer_safe_summary:
      'A human reviewer confirmed that the request cannot proceed based on the current evidence and prototype rules.',
  },
};

const finalConfiguration =
  outcomeConfiguration[reviewerDecision];

const completedAt =
  new Date().toISOString();

const existingSecondaryReasons =
  String(
    reviewPackage.original_secondary_reason_codes || ''
  )
    .split(';')
    .map(value => value.trim())
    .filter(Boolean);

const finalSecondaryReasons = [
  ...new Set([
    ...existingSecondaryReasons,
    'HUMAN_REVIEW_COMPLETED',
  ]),
];

const humanReview = {
  review_id:
    reviewPackage.review_id,

  reviewer_name:
    reviewerName,

  reviewer_decision:
    reviewerDecision,

  reviewer_comments:
    reviewerComments,

  override_reason:
    overrideReason,

  completed_at:
    completedAt,
};

const finalDecisionJson = {
  case_run_id:
    reviewPackage.case_run_id,

  submission_version:
    reviewPackage.submission_version,

  original_outcome:
    reviewPackage.original_outcome,

  final_outcome:
    reviewerDecision,

  primary_reason_code:
    reviewPackage.original_primary_reason_code,

  secondary_reason_codes:
    finalSecondaryReasons,

  human_review_required:
    false,

  target_queue:
    finalConfiguration.target_queue,

  next_action:
    finalConfiguration.next_action,

  customer_safe_summary:
    finalConfiguration.customer_safe_summary,

  communication_template_id:
    finalConfiguration.communication_template_id,

  human_review:
    humanReview,

  prototype_data:
    true,

  production_write_performed:
    false,
};

return [
  {
    json: {
      ...reviewPackage,

      reviewer_name:
        reviewerName,

      reviewer_decision:
        reviewerDecision,

      reviewer_comments:
        reviewerComments,

      override_reason:
        overrideReason,

      final_outcome:
        reviewerDecision,

      final_target_queue:
        finalConfiguration.target_queue,

      final_next_action:
        finalConfiguration.next_action,

      final_customer_safe_summary:
        finalConfiguration.customer_safe_summary,

      final_communication_template_id:
        finalConfiguration.communication_template_id,

      final_secondary_reason_codes:
        finalSecondaryReasons,

      human_review_required:
        false,

      final_review_status:
        'COMPLETED',

      completed_at:
        completedAt,

      final_decision_json:
        finalDecisionJson,
    },
  },
];

return [
  {
    json:
      $('Build Human Review Communication').first().json
  }
];

const review =
  $('Validate Reviewer Submission').first().json;

const template =
  $('Get Human Review Communication Template').first().json;

const values = {
  case_id:
    review.case_run_id,

  business_name:
    review.business_name,

  representative_name:
    review.representative_name,

  outcome:
    review.final_outcome,

  reason_code:
    review.original_primary_reason_code,

  queue:
    review.final_target_queue,

  next_action:
    review.final_next_action,

  missing_items:
    review.final_outcome === 'NEED_MORE_INFORMATION'
      ? review.reviewer_comments
      : (
          review.original_missing_information ||
          'Please refer to the reviewer comments.'
        ),
};

function fillTemplate(text = '') {
  return String(text).replace(
    /\{(\w+)\}/g,
    (match, key) =>
      values[key] !== undefined
        ? String(values[key])
        : match
  );
}

return [
  {
    json: {
      ...review,

      communication: {
        communication_id:
          `COMM-${review.case_run_id}-V${review.submission_version}-HUMAN`,

        audience:
          template.Audience,

        template_id:
          template.Template_ID,

        subject:
          fillTemplate(template.Subject_Template),

        body:
          fillTemplate(template.Body_Template),

        status:
          'DRAFT',

        approval_required:
          true,

        sent:
          false,

        created_at:
          new Date().toISOString(),
      },
    },
  },
];

const input =
  $('Open Resubmission').first().json;

const decision =
  $('Get Original Decision').first().json || {};

const found =
  Boolean(decision.case_run_id);

const outcome =
  String(decision.outcome || '').toUpperCase();

const eligible =
  found &&
  outcome === 'NEED_MORE_INFORMATION';

return [
  {
    json: {
      original_case_run_id:
        input.original_case_run_id,

      revised_case_run_id:
        input.revised_case_run_id,

      resubmission_comments:
        input.resubmission_comments,

      original_decision_found:
        found,

      original_outcome:
        outcome,

      resubmission_eligible:
        eligible,
    },
  },
];

const original =
  $('Get Original Case').first().json;

const revised =
  $('Get Revised Case').first().json;

const sameLogicalCase =
  original.Case_ID === revised.Case_ID;

const originalVersion =
  Number(original.Submission_Version);

const revisedVersion =
  Number(revised.Submission_Version);

const versionIncreased =
  revisedVersion > originalVersion;

const differentRun =
  original.Case_Run_ID !== revised.Case_Run_ID;

const valid =
  sameLogicalCase &&
  versionIncreased &&
  differentRun;

return [
  {
    json: {
      original_case_run_id:
        original.Case_Run_ID,

      revised_case_run_id:
        revised.Case_Run_ID,

      logical_case_id:
        original.Case_ID,

      original_version:
        originalVersion,

      revised_version:
        revisedVersion,

      same_logical_case:
        sameLogicalCase,

      version_increased:
        versionIncreased,

      relationship_valid:
        valid,
    },
  },
];

const original =
  $('Get Original Case').first().json;

const revised =
  $('Get Revised Case').first().json;

const revisedDecision =
  $('Run Revised SBO.02 Assessment').first().json;

return [
  {
    json: {
      original_case_run_id:
        original.Case_Run_ID,

      original_case_id:
        original.Case_ID,

      original_submission_version:
        Number(original.Submission_Version),

      revised_case_run_id:
        revised.Case_Run_ID,

      revised_submission_version:
        Number(revised.Submission_Version),

      revised_outcome:
        revisedDecision.outcome,

      original_new_status:
        'SUPERSEDED_BY_RESUBMISSION',

      original_new_stage:
        'RESUBMITTED',

      updated_at:
        new Date().toISOString()
    }
  }
];

return [
  {
    json:
      $('Run Revised SBO.02 Assessment').first().json
  }
];

const input =
  $('Receive Evidence Resolution Request')
    .first()
    .json;

const request =
  $('Get Evidence Request')
    .first()
    .json || {};

const requestFound =
  Boolean(
    String(
      request.evidence_request_id || ''
    ).trim()
  );

const caseMatches =
  String(
    request.case_run_id || ''
  ).trim() ===
  String(
    input.case_run_id || ''
  ).trim();

const versionMatches =
  Number(
    request.submission_version
  ) ===
  Number(
    input.submission_version
  );

const requestStatus =
  String(
    request.status || ''
  )
    .trim()
    .toUpperCase();

const permittedStatuses = [
  'RECEIVED',
  'PARTIALLY_RECEIVED',
  'INSUFFICIENT',
];

const statusPermitted =
  permittedStatuses.includes(
    requestStatus
  );

return [
  {
    json: {
      request_valid:
        requestFound &&
        caseMatches &&
        versionMatches &&
        statusPermitted,

      request_found:
        requestFound,

      case_matches:
        caseMatches,

      version_matches:
        versionMatches,

      status_permitted:
        statusPermitted,

      current_request_status:
        requestStatus,

      evidence_request_id:
        input.evidence_request_id,

      case_run_id:
        input.case_run_id,

      submission_version:
        Number(
          input.submission_version
        ),
    },
  },
];

const records =
  $input
    .all()
    .map(item => item.json)
    .filter(row =>
      String(
        row.evidence_id || ''
      ).trim()
    );

const activeRecords =
  records.filter(row => {
    const status =
      String(
        row.validation_status || ''
      )
        .trim()
        .toUpperCase();

    return ![
      'REJECTED',
      'SUPERSEDED',
    ].includes(status);
  });

return [
  {
    json: {
      evidence_records_exist:
        activeRecords.length > 0,

      evidence_record_count:
        activeRecords.length,

      evidence_ids:
        activeRecords
          .map(row =>
            row.evidence_id
          )
          .filter(Boolean),
    },
  },
];

const request =
  $('Get Evidence Request')
    .first()
    .json;

const caseRow =
  $('Get Evidence Case')
    .first()
    .json;

const evidenceRecords =
  $('Get Evidence Records')
    .all()
    .map(item => item.json)
    .filter(row =>
      String(
        row.evidence_id || ''
      ).trim()
    )
    .filter(row => {
      const status =
        String(
          row.validation_status || ''
        )
          .trim()
          .toUpperCase();

      return ![
        'REJECTED',
        'SUPERSEDED',
      ].includes(status);
    });

let requestedItems = [];

try {
  requestedItems =
    JSON.parse(
      request.requested_items_json ||
      '[]'
    );
} catch {
  requestedItems = [
    String(
      request.requested_items_json ||
      ''
    ),
  ].filter(Boolean);
}

return [
  {
    json: {
      evidence_request: {
        evidence_request_id:
          request.evidence_request_id,

        case_run_id:
          request.case_run_id,

        submission_version:
          Number(
            request.submission_version || 1
          ),

        originating_check_type:
          request.originating_check_type,

        originating_reason_code:
          request.originating_reason_code,

        evidence_channel:
          request.evidence_channel,

        requested_items:
          requestedItems,

        attempt_count:
          Number(
            request.attempt_count || 0
          ),

        max_attempts:
          Number(
            request.max_attempts || 3
          ),
      },

      case_context: {
        case_run_id:
          caseRow.Case_Run_ID,

        logical_case_id:
          caseRow.Case_ID,

        country:
          caseRow.Country,

        request_type:
          caseRow.Request_Type,

        business_name:
          caseRow.Business_Name_Submitted,

        business_identifier:
          caseRow.Business_Identifier_Submitted,

        customer_id:
          caseRow.Customer_ID,

        representative_name:
          caseRow.Representative_Name,

        representative_role:
          caseRow.Representative_Role,

        requested_authority:
          caseRow.Requested_Authority,

        request_narrative:
          caseRow.Customer_Request_Narrative,
      },

      evidence_records:
        evidenceRecords.map(row => ({
          evidence_id:
            row.evidence_id,

          evidence_type:
            row.evidence_type,

          evidence_source:
            row.evidence_source,

          file_name:
            row.file_name,

          mime_type:
            row.mime_type,

          evidence_text:
            row.evidence_text,

          structured_data_json:
            row.structured_data_json,

          provided_at:
            row.provided_at,
        })),
    },
  },
];

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "resolution_status": {
      "type": "string",
      "enum": [
        "RESOLVED",
        "PARTIAL",
        "INSUFFICIENT",
        "CONTRADICTORY"
      ],
      "description": "The resolution of the exact originating evidence gap."
    },
    "resolved": {
      "type": "boolean",
      "description": "True only when resolution_status is RESOLVED."
    },
    "supported_facts": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Facts explicitly supported by the submitted evidence."
    },
    "remaining_gaps": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Relevant evidence requirements that remain unresolved."
    },
    "reason_codes": {
      "type": "array",
      "items": {
        "type": "string"
      },
      "description": "Reason codes supporting the evidence-resolution result."
    },
    "recommended_next_action": {
      "type": "string",
      "description": "The next operational action after this evidence assessment."
    },
    "confidence": {
      "type": "number",
      "minimum": 0,
      "maximum": 1,
      "description": "Confidence in the evidence-resolution result."
    }
  },
  "required": [
    "resolution_status",
    "resolved",
    "supported_facts",
    "remaining_gaps",
    "reason_codes",
    "recommended_next_action",
    "confidence"
  ]
}

parameters.jsCode:
const context =
  $('Prepare Resolution Context')
    .first()
    .json;

const request =
  context.evidence_request;

// The Basic LLM Chain may return the parsed object directly,
// or place it under output, text, or response.
let resolution =
  $json.output ??
  $json.text ??
  $json.response ??
  $json;

// Handle nested parser output.
if (
  resolution &&
  typeof resolution === 'object' &&
  !Array.isArray(resolution) &&
  resolution.output !== undefined
) {
  resolution =
    resolution.output;
}

// Handle JSON returned as text.
if (typeof resolution === 'string') {
  const cleaned =
    resolution
      .trim()
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '');

  try {
    resolution =
      JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      `Evidence-resolution output could not be parsed as JSON: ${error.message}`
    );
  }
}

if (
  !resolution ||
  typeof resolution !== 'object' ||
  Array.isArray(resolution)
) {
  throw new Error(
    'Evidence-resolution output is not a valid JSON object.'
  );
}

function stringArray(value) {
  if (!Array.isArray(value)) {
    return [];
  }

  return value
    .map(item => {
      if (typeof item === 'string') {
        return item.trim();
      }

      if (
        item !== null &&
        item !== undefined
      ) {
        return JSON.stringify(item);
      }

      return '';
    })
    .filter(Boolean);
}

const permittedResolutionStatuses = [
  'RESOLVED',
  'PARTIAL',
  'INSUFFICIENT',
  'CONTRADICTORY',
];

let resolutionStatus =
  String(
    resolution.resolution_status ||
    'INSUFFICIENT'
  )
    .trim()
    .toUpperCase();

if (
  !permittedResolutionStatuses.includes(
    resolutionStatus
  )
) {
  resolutionStatus =
    'INSUFFICIENT';
}

const checkType =
  String(
    request.originating_check_type ||
    'REQUEST_CLARIFICATION'
  )
    .trim()
    .toUpperCase();

const sequenceMap = {
  REQUEST_CLARIFICATION: 0,
  CUSTOMER_CONFIRMATION: 0,
  SALES_CONFIRMATION: 0,
  DOCUMENT_EXTRACTION: 1,
  BUSINESS_VALIDATION: 2,
  IDENTITY_VALIDATION: 3,
  AUTHORITY_VALIDATION: 4,
  SYSTEM_DATA_CHECK: 5,
  FINANCIAL_CHECK: 6,
  FINAL_VERIFICATION: 7,
};

const sequence =
  sequenceMap[checkType] ?? 0;

const currentAttemptCount =
  Number(
    request.attempt_count || 0
  ) + 1;

const maxAttempts =
  Number(
    request.max_attempts || 3
  );

const supportedFacts =
  stringArray(
    resolution.supported_facts
  );

const remainingGaps =
  stringArray(
    resolution.remaining_gaps
  );

const modelReasonCodes =
  stringArray(
    resolution.reason_codes
  );

const evidenceReferences =
  context.evidence_records
    .map(record =>
      String(
        record.evidence_id || ''
      ).trim()
    )
    .filter(Boolean);

const rawConfidence =
  Number(
    resolution.confidence
  );

const confidence =
  Number.isFinite(rawConfidence)
    ? Math.max(
        0,
        Math.min(
          1,
          rawConfidence
        )
      )
    : 0;

let status;
let terminalOutcome;
let ruleId;
let primaryResolutionReason;
let humanReviewRequired;
let requestStatus;
let retryAllowed;
let escalationRequired;
let fallbackNextAction;

switch (resolutionStatus) {
  case 'RESOLVED':
    status =
      'PASS';

    /*
    EVID-001 resolves the originating check.
    It is not a fifth whole-case outcome.
    */
    terminalOutcome =
      '';

    ruleId =
      'EVID-001';

    primaryResolutionReason =
      'ADDITIONAL_EVIDENCE_ACCEPTED';

    humanReviewRequired =
      false;

    requestStatus =
      'ACCEPTED';

    retryAllowed =
      false;

    escalationRequired =
      false;

    fallbackNextAction =
      'Resume processing from the next incomplete mandatory check.';

    break;

  case 'CONTRADICTORY':
    status =
      'INCONCLUSIVE';

    terminalOutcome =
      'MANUAL_REVIEW';

    ruleId =
      'EVID-003';

    primaryResolutionReason =
      'ADDITIONAL_EVIDENCE_CONTRADICTORY';

    humanReviewRequired =
      true;

    requestStatus =
      'ESCALATED';

    retryAllowed =
      false;

    escalationRequired =
      true;

    fallbackNextAction =
      'Route the case and conflicting evidence to human evidence review.';

    break;

  case 'PARTIAL':
  case 'INSUFFICIENT':
  default:
    status =
      'INCONCLUSIVE';

    terminalOutcome =
      'NEED_MORE_INFORMATION';

    ruleId =
      'EVID-002';

    primaryResolutionReason =
      'ADDITIONAL_EVIDENCE_INSUFFICIENT';

    /*
    EVID-002 itself remains customer-remediable.
    Operational human escalation is created later only when
    the maximum number of attempts has been exhausted.
    */
    humanReviewRequired =
      false;

    retryAllowed =
      currentAttemptCount <
      maxAttempts;

    requestStatus =
      retryAllowed
        ? 'INSUFFICIENT'
        : 'ESCALATED';

    escalationRequired =
      !retryAllowed;

    fallbackNextAction =
      retryAllowed
        ? 'Request the specific remaining evidence and keep the case open.'
        : 'Route the unresolved evidence request to a human evidence reviewer.';

    break;
}

const recommendedNextStep =
  String(
    resolution.recommended_next_action ||
    fallbackNextAction
  ).trim();

const reasonCodes = [
  ...new Set([
    primaryResolutionReason,
    ...modelReasonCodes,
  ]),
];

const resultId =
  `RES-${request.case_run_id}-V${Number(
    request.submission_version || 1
  )}-${checkType}`;

return [
  {
    json: {
      result_id:
        resultId,

      case_run_id:
        request.case_run_id,

      submission_version:
        Number(
          request.submission_version || 1
        ),

      sequence,

      agent_id:
        'SBO.02',

      utility_name:
        'Evidence Resolution Utility',

      /*
      Retain the originating mandatory check type.
      This allows the row to replace the previous failed or
      inconclusive result for that same check.
      */
      check_type:
        checkType,

      status,

      findings: {
        evidence_resolution:
          true,

        evidence_request_id:
          request.evidence_request_id,

        resolution_status:
          resolutionStatus,

        resolved:
          resolutionStatus ===
          'RESOLVED',

        supported_facts:
          supportedFacts,

        remaining_gaps:
          remainingGaps,

        evidence_count:
          evidenceReferences.length,
      },

      reason_codes:
        reasonCodes,

      evidence_references:
        evidenceReferences,

      confidence,

      human_review_required:
        humanReviewRequired,

      recommended_next_step:
        recommendedNextStep,

      rule_ids: [
        ruleId,
      ],

      rule_status_used:
        'CONFIRMED_POC',

      is_terminal:
        Boolean(
          terminalOutcome
        ),

      terminal_outcome:
        terminalOutcome,

      evidence_request_id:
        request.evidence_request_id,

      resolution_status:
        resolutionStatus,

      current_attempt_count:
        currentAttemptCount,

      max_attempts:
        maxAttempts,

      retry_allowed:
        retryAllowed,

      escalation_required:
        escalationRequired,

      evidence_request_status:
        requestStatus,
    },
  },
];

return [
  {
    json:
      $('Build Resolved Utility Result')
        .first()
        .json,
  },
];

/*
============================================================
VALIDATE EVIDENCE REQUEST
============================================================

The evidence-request table row is the authoritative source
for case_run_id.

Rules:
- Evidence request must exist.
- Status must permit evidence submission.
- If the form supplied a case ID, it must match.
- If the form omitted case ID, use the stored case ID.
============================================================
*/

const submitted =
  $('Normalise Evidence Upload Input')
    .first()
    .json || {};

const requestRows =
  $input
    .all()
    .map(item =>
      item.json || {}
    )
    .filter(row =>
      String(
        row.evidence_request_id || ''
      ).trim()
    );

const request =
  requestRows[0] || {};

const submittedEvidenceRequestId =
  String(
    submitted.evidence_request_id || ''
  ).trim();

const storedEvidenceRequestId =
  String(
    request.evidence_request_id || ''
  ).trim();

const suppliedCaseRunId =
  String(
    submitted.supplied_case_run_id ||
    submitted.case_run_id ||
    ''
  ).trim();

const storedCaseRunId =
  String(
    request.case_run_id || ''
  ).trim();

const currentStatus =
  String(
    request.status || ''
  )
    .trim()
    .toUpperCase();

const permittedStatuses = [
  'OPEN',
  'PARTIALLY_RECEIVED',
  'INSUFFICIENT',
];

const requestFound =
  Boolean(
    storedEvidenceRequestId
  );

const requestIdMatches =
  requestFound &&
  storedEvidenceRequestId ===
    submittedEvidenceRequestId;

/*
A missing supplied case ID is acceptable because the request
record already owns the authoritative case ID.

A supplied but different case ID is not acceptable.
*/
const caseMismatch =
  Boolean(
    suppliedCaseRunId &&
    storedCaseRunId &&
    suppliedCaseRunId !==
      storedCaseRunId
  );

const statusPermitted =
  permittedStatuses.includes(
    currentStatus
  );

const effectiveCaseRunId =
  storedCaseRunId ||
  suppliedCaseRunId;

const uploadAllowed =
  requestFound &&
  requestIdMatches &&
  Boolean(
    effectiveCaseRunId
  ) &&
  !caseMismatch &&
  statusPermitted;

let rejectionReason = '';

if (!submittedEvidenceRequestId) {
  rejectionReason =
    'EVIDENCE_REQUEST_ID_NOT_SUPPLIED';
} else if (!requestFound) {
  rejectionReason =
    'EVIDENCE_REQUEST_NOT_FOUND';
} else if (!requestIdMatches) {
  rejectionReason =
    'EVIDENCE_REQUEST_ID_MISMATCH';
} else if (!effectiveCaseRunId) {
  rejectionReason =
    'CASE_RUN_ID_NOT_AVAILABLE';
} else if (caseMismatch) {
  rejectionReason =
    'CASE_RUN_ID_MISMATCH';
} else if (!statusPermitted) {
  rejectionReason =
    'EVIDENCE_REQUEST_NOT_OPEN';
}

return [
  {
    json: {
      evidence_request_id:
        storedEvidenceRequestId ||
        submittedEvidenceRequestId,

      /*
      Authoritative effective value used downstream.
      */
      case_run_id:
        effectiveCaseRunId,

      supplied_case_run_id:
        suppliedCaseRunId,

      stored_case_run_id:
        storedCaseRunId,

      current_status:
        currentStatus,

      request_found:
        requestFound,

      request_id_matches:
        requestIdMatches,

      case_mismatch:
        caseMismatch,

      status_permitted:
        statusPermitted,

      upload_allowed:
        uploadAllowed,

      rejection_reason:
        rejectionReason,

      submission_version:
        Number(
          request.submission_version || 1
        ),

      originating_check_type:
        String(
          request.originating_check_type ||
          ''
        ).trim(),

      evidence_channel:
        String(
          request.evidence_channel ||
          ''
        ).trim(),

      evidence_acceptance_policy:
        String(
          request.evidence_acceptance_policy ||
          ''
        ).trim(),

      request_row:
        request,
    },

    /*
    Preserve the uploaded file through validation.
    */
    binary:
      $('Normalise Evidence Upload Input')
        .first()
        .binary || {},
  },
];

const extracted =
  $json || {};

const candidates = [
  extracted.text,
  extracted.content,
  extracted.data,
  extracted.document?.text,
  extracted.pages,
];

let text = '';

for (const candidate of candidates) {
  if (
    candidate !== undefined &&
    candidate !== null
  ) {
    if (typeof candidate === 'string') {
      text = candidate.trim();
      break;
    }

    if (Array.isArray(candidate)) {
      text = candidate
        .map(item =>
          typeof item === 'string'
            ? item
            : (
                item.text ??
                item.content ??
                JSON.stringify(item)
              )
        )
        .join('\n')
        .trim();

      if (text) {
        break;
      }
    }
  }
}

return [
  {
    json: {
      extracted_text:
        text,

      text_available:
        text.length >= 20,

      extracted_character_count:
        text.length,
    },
  },
];

/*
============================================================
NORMALISE EVIDENCE UPLOAD INPUT
============================================================

Reads IDs defensively from possible Form Trigger payload shapes.

Also preserves the uploaded binary PDF.
============================================================
*/

const item =
  $input.first() || {};

const input =
  item.json || {};

const body =
  input.body &&
  typeof input.body === 'object'
    ? input.body
    : {};

const query =
  input.query &&
  typeof input.query === 'object'
    ? input.query
    : {};

const formData =
  input.formData &&
  typeof input.formData === 'object'
    ? input.formData
    : {};

const data =
  input.data &&
  typeof input.data === 'object'
    ? input.data
    : {};

function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return String(value).trim();
    }
  }

  return '';
}

const evidenceRequestId =
  firstNonEmpty(
    input.evidence_request_id,
    body.evidence_request_id,
    query.evidence_request_id,
    formData.evidence_request_id,
    data.evidence_request_id
  );

const caseRunId =
  firstNonEmpty(
    input.case_run_id,
    body.case_run_id,
    query.case_run_id,
    formData.case_run_id,
    data.case_run_id
  );

return [
  {
    json: {
      ...input,

      evidence_request_id:
        evidenceRequestId,

      /*
      This remains the customer/form-supplied value.
      The authoritative value will be retrieved from
      dt_evidence_requests later.
      */
      supplied_case_run_id:
        caseRunId,

      case_run_id:
        caseRunId,

      upload_input_received_at:
        new Date().toISOString(),
    },

    /*
    Preserve the uploaded file.
    */
    binary:
      item.binary || {},
  },
];
